import { useMemo, useState, type ComponentProps, type FormEvent, type ReactNode } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import {
  Activity, AlertTriangle, ArrowDownRight, ArrowRight, ArrowUpRight, BarChart3, Building2, CalendarCheck,
  Camera, Check, CheckCircle2, ChevronDown, CircleHelp, ClipboardCheck, Cloud, Download, ExternalLink,
  FileCheck2, FilePlus2, FileSpreadsheet, FileText, Filter, FlaskConical, FolderKanban, HardHat, Image,
  Info, LoaderCircle, LockKeyhole, MessageSquareText, MoreHorizontal, Plus, RefreshCw, Search, Send,
  ShieldAlert, ShieldCheck, Sparkles, UploadCloud, Users, Video, Wallet, Wrench, X, Zap,
} from 'lucide-react';
import { api, ApiError } from '../api';
import { useResource } from '../hooks';
import type {
  AuditRecord, Camera as CameraRecord, DailyReport, DashboardData, DocumentRecord, Estimate, EstimateItem,
  Experiment, Intervention, Invoice, Notification, Project, Role, SafetyEvent, TeamMember, User,
} from '../types';
import {
  Badge, Button, Card, DataState, EmptyState, ErrorState, FormField, InlineNotice, LoadingState, Modal,
  PageHeader, SectionTitle, currency, dateLabel, initials, shortDate, toneFor,
} from '../components/ui';

function useMutationNotice() {
  const [notice, setNotice] = useState<{ tone: 'success' | 'error' | 'info'; message: string } | null>(null);
  function renderNotice() { return notice ? <div className="notice-wrap"><InlineNotice tone={notice.tone}>{notice.message}</InlineNotice></div> : null; }
  return { notice, setNotice, renderNotice };
}
function ProjectSelect({ projects, value, onChange, required = true }: { projects: Project[]; value: string; onChange: (value: string) => void; required?: boolean }) {
  return <select value={value} onChange={e => onChange(e.target.value)} required={required}><option value="">Select a project</option>{projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select>;
}
function TableHead({ columns }: { columns: string[] }) { return <thead><tr>{columns.map(c => <th key={c}>{c}</th>)}</tr></thead>; }
function MetricCard({ label, value, helper, icon: Icon, color = 'plum', trend }: { label: string; value: string | number; helper: string; icon: typeof Activity; color?: string; trend?: 'up' | 'down' }) {
  return <Card className="metric-card"><div className={`metric-icon metric-${color}`}><Icon size={19} /></div><div className="metric-label">{label}</div><div className="metric-value">{value}</div><div className="metric-helper">{trend && <span className={trend === 'up' ? 'trend-up' : 'trend-down'}>{trend === 'up' ? <ArrowUpRight size={13} /> : <ArrowDownRight size={13} />}</span>}{helper}</div></Card>;
}
function SeverityPill({ value }: { value: string }) { return <Badge tone={toneFor(value)}>{value.replaceAll('_', ' ')}</Badge>; }
function ProjectProgress({ progress }: { progress: number }) { return <div className="progress-wrap"><div className="progress-bar"><span style={{ width: `${Math.max(0, Math.min(progress || 0, 100))}%` }} /></div><span>{progress || 0}%</span></div>; }
function AvatarStack({ count = 3 }: { count?: number }) { return <div className="avatar-stack">{['AD', 'IK', 'RP'].slice(0, count).map((a, i) => <span className={`tiny-avatar tiny-avatar-${i}`} key={a}>{a}</span>)}{count > 3 && <span className="tiny-avatar tiny-avatar-more">+{count - 3}</span>}</div>; }
function EmptyTable({ text }: { text: string }) { return <tr><td colSpan={10}><div className="table-empty">{text}</div></td></tr>; }
function statusLabel(status?: string) { return (status || 'UNKNOWN').replaceAll('_', ' '); }

