            <DataState loading={false} error={null} reload={reload} empty={!data.projects.length}><div className="project-list">{data.projects.slice(0, 4).map(project => <Link to={`/projects/${project.id}`} className="project-row" key={project.id}><div className={`project-thumb project-thumb-${data.projects.indexOf(project) % 4}`}><Building2 size={23} /></div><div className="project-row-main"><strong>{project.name}</strong><span><span className="muted-pin" />{project.location || 'Location not recorded'} · {project.clientName}</span><ProjectProgress progress={project.progress} /></div><div className="project-row-side"><Badge tone={toneFor(project.status)}>{statusLabel(project.status)}</Badge><strong>{currency(project.budget)}</strong><small>Project budget</small></div><ChevronDown className="row-chevron" size={17} /></Link>)}</div></DataState>
