    <Card><SectionTitle title="Project context" detail="Select a project to keep plan and visualization requests associated with the right workspace." /><DataState loading={loading} error={error} reload={reload} empty={!projects?.length}><div className="simple-table-wrap"><table><TableHead columns={['Project', 'Location', 'Stage', 'Progress', 'Action']} /><tbody>{projects?.map(p => <tr key={p.id}><td><strong>{p.name}</strong><small>{p.clientName}</small></td><td>{p.location}</td><td><Badge tone={toneFor(p.status)}>{statusLabel(p.status)}</Badge></td><td><ProjectProgress progress={p.progress} /></td><td><Button size="sm" variant="outline" onClick={() => navigate(`/projects/${p.id}`)}>Workspace <ArrowUpRight size={14} /></Button></td></tr>)}</tbody></table></div></DataState></Card>
